  txNoInvest: row(["Beleggings vat net oorskot, binne hierdie week se limiet.", "Ukutshala kuthatha eseleyo kuphela, ngaphakathi komkhawulo waleli viki.", "Utyalo-mali luthatha eseleyo kuphela, ngaphakathi komda wale veki.", "Ukutshala kuthatha eseleyo kuphela, ngaphakathi komkhawulo.", "Kutjala kutfola lesele kuphela, ngekhatsi kwemkhawulo.", "Matsetelo a nka e setseng feela, ka har'a moeli oa beke ena.", "Ditsetelo di nka ye šetšego feela, ka gare ga moedi wa beke ye.", "Ditsetelo di nka a setseng fela, mo gare ga moedi wa beke eno.", "Mintshalo yi teka leyi salaka ntsena, endzeni ka nkatsakanyo wa vhiki leri.", "Vhutseteli vhu dzhia zwo salaho fhedzi, nga ngomu ha mukano wa vhege iyi.", "Investments only take leftover, inside this week's cap."]),
  txNoLesson: row(["Voltooi eers die oorskot-les.", "Qeda isifundo seseleyo kuqala.", "Gqiba isifundo seseleyo kuqala.", "Qeda isifundo seseleyo kuqala.", "Cedza sifundvo selesele kucala.", "Qeta thuto ea e setseng pele.", "Feditša thuto ya ye šetšego pele.", "Fetsa thuto ya a setseng pele.", "Hetelela dyondzo ya leyi salaka ku sungula.", "Fhedzisani tshifundo tsha zwo salaho u thoma.", "Finish the leftover lesson first."]),
  txNoLeftover: row(["Geen oorskot hierdie week nie. Sit is die strategie.", "Ayikho eseleyo kuleli viki. Ukuhlala phansi yisu.", "Akukho eseleyo kule veki. Ukuhlala phantsi licebo.", "Ayikho eseleyo kulo viki. Ukuhlala phansi yisu.", "Ayikho lesele kuliviki. Kuhlala phansi yisu.", "Ha ho e setseng bekeng ena. Ho lula ke leano.", "Ga go na ye šetšego bekeng ye. Go dula ke leano.", "Ga go na a setseng bekeng eno. Go nna fatshe ke leano.", "A ku na leyi salaka evhikini leri. Ku tshama i qhinga.", "A huna zwo salaho kha vhege iyi. U dzula ndi tshikimu.", "No leftover this week. Sitting is the strategy."]),
  txNoCap: row(["Hierdie week se oorskot-limiet vir Beleggings is {amount}.", "Umkhawulo weseleyo waleli viki wezokutshala ungu-{amount}.", "Umda weseleyo wale veki wotyalo-mali ngu-{amount}.", "Umkhawulo weseleyo walo viki ungu-{amount}.", "Umkhawulo welesele waleliviki ngu-{amount}.", "Moeli oa e setseng oa beke ena bakeng sa Matsetelo ke {amount}.", "Moedi wa ye šetšego wa beke ye bakeng sa Ditsetelo ke {amount}.", "Moedi wa a setseng wa beke eno bakeng sa Ditsetelo ke {amount}.", "Nkatsakanyo wa leyi salaka wa vhiki leri eka Mintshalo i {amount}.", "Mukano wa zwo salaho wa vhege iyi kha Vhutseteli ndi {amount}.", "This week's leftover cap for Investments is {amount}."]),
  txNoBuffer: row(["Spaargeld koop nie aandele nie. Skuif eers na Main, parkeer dan oorskot in Beleggings.", "Imali egciniwe ayithengi amasheya. Hambisa ku-Main kuqala, bese upaka eseleyo ku-Investments.", "Imali egciniweyo ayithengi izabelo. Hambisa ku-Main kuqala, upake eseleyo ku-Investments.", "Imali egciniwe ayithengi amasheya. Hambisa ku-Main kuqala.", "Imali legciniwe ayithengi emasheya. Hambisa ku-Main kucala.", "Polokelo ha e reke liabo. Tsamaisa ho Main pele, ebe u emisa e setseng ho Matsetelo.", "Polokelo ga e reke diabe. Iša go Main pele, ke moka o emise ye šetšego go Ditsetelo.", "Polokelo ga e reke diabe. Isa mo Main pele, mme o emise a setseng mo Ditsetelo.", "Ntsako a wu xavi swiphemu. Rhumela eka Main ku sungula, kutani u yimisa leyi salaka eka Mintshalo.", "Vhulunga a zwi rengi zwipida. Isani kha Main u thoma, nga murahu ni ime zwo salaho kha Vhutseteli.", "Savings does not buy shares. Move to Main first, then park leftover in Investments."]),
  txInvestNote: row(["Die oorskot-pad: Spaargeld → Main → Beleggings → Shares Zero. Huur slaan nooit die ry oor nie.", "Indlela yeseleyo: Imali egciniwe → Main → Ukutshala → Shares Zero. Irenti ayigqizi umugqa.", "Indlela yeseleyo: Imali egciniweyo → Main → Utyalo-mali → Shares Zero. Irenti ayitsibi umgca.", "Indlela yeseleyo: Imali egciniwe → Main → Ukutshala → Shares Zero.", "Indlela yelesele: Imali legciniwe → Main → Kutjala → Shares Zero.", "Tsela ea e setseng: Polokelo → Main → Matsetelo → Shares Zero. Rente ha e tloloe.", "Tsela ya ye šetšego: Polokelo → Main → Ditsetelo → Shares Zero. Rente ga e tlolwe.", "Tsela ya a setseng: Polokelo → Main → Ditsetelo → Shares Zero. Rente ga e tlolwe.", "Ndhlela ya leyi salaka: Ntsako → Main → Mintshalo → Shares Zero. Rente a yi tluli layini.", "Nndila ya zwo salaho: Vhulunga → Main → Vhutseteli → Shares Zero. Rente a i fhiri mutalo.", "The leftover path: Savings → Main → Investments → Shares Zero. Rent never skips the line."]),
  coachTitle: row(["Vra die desk", "Buza idesiki", "Buza idesika", "Buza idesiki", "Buta idesiki", "Botsa deseke", "Botšiša deseke", "Botsa deseke", "Vutisa desiki", "Vhudzisa desiki", "ASK the desk"]),
  coachSub: row(["Jou oorskot-bot. Antwoorde gebruik jóú oorskot en vooruitskatting, nooit ’n hot tip nie.", "Ibhothi yeseleyo yakho. Izimpendulo zisebenzisa eseleyo yakho neqagelo, hhayi ithiphu eshisayo.", "Ibhothi yeseleyo yakho. Iimpendulo zisebenzisa eseleyo yakho noqikelelo, hayi ithiphu eshushu.", "Ibhothi yeseleyo yakho. Izimpendulo zisebenzisa eseleyo neqagelo, hhayi ithiphu.", "Ibhothi yelesele yakho. Timphendvulo tisebentisa lesele nesibikezelo, hhayi thiphu.", "Bot ea hau ea e setseng. Likarabo li sebelisa e setseng ea hau le tlhahiso-pele, eseng keletso e chesang.", "Bot ya gago ya ye šetšego. Dikarabo di šomiša ye šetšego ya gago le ponelopele, e sego keletšo ye fišago.", "Bot ya gago ya a setseng. Dikarabo di dirisa a setseng a gago le ponelopele, eseng keletso e fisang.", "Bot ya wena ya leyi salaka. Tinhlamulo ti tirhisa leyi salaka ya wena na vuprofeta, ku nga ri xileriso xo hisa.", "Bot yanu ya zwo salaho. Phindulo i shumisa zwo salaho zwanu na mbonalo, hu si tshivhudzo tsho fhisa.", "Your leftover bot. Answers use your own leftover and forecast, never a hot tip."]),
  coachHello: row(["Haai. Ek is die Compound Confidence-bot. Vra oor oorskot, ’n misgeloopte gig, of of jy moet sit hierdie week.", "Sawubona. Ngiyi-bot ye-Compound Confidence. Buza ngeseleyo, i-gig ephuthelwe, noma ukuthi kumele uhlale phansi kuleli viki.", "Molo. Ndiyibhothi ye-Compound Confidence. Buza ngeseleyo, i-gig ephuthelweyo, okanye ukuba kufuneka uhlale phantsi kule veki.", "Sawubona. Ngiyi-bot ye-Compound Confidence. Buza ngeseleyo noma ukuhlala phansi.", "Sawubona. Ngiyi-bot ye-Compound Confidence. Buta ngelesele noma kuhlala phansi.", "Lumela. Ke bot ea Compound Confidence. Botsa ka e setseng, gig e fositseng, kapa hore na u lokela ho lula bekeng ena.", "Dumela. Ke bot ya Compound Confidence. Botšiša ka ye šetšego, gig e fositšego, goba gore o swanetše go dula bekeng ye.", "Dumela. Ke bot ya Compound Confidence. Botsa ka a setseng, gig e fositseng, kgotsa gore o tshwanetse go nna fatshe bekeng eno.", "Avuxeni. Ndzi bot ya Compound Confidence. Vutisa hi leyi salaka, gig leyi lahlekeke, kumbe loko u fanele ku tshama evhikini leri.", "Ndaa. Ndi bot ya Compound Confidence. Vhudzisani nga zwo salaho, gig yo xela, kana arali ni tea u dzula kha vhege iyi.", "HEY. I'm the Compound Confidence bot. Ask about leftover, a missed gig, or whether you should sit this week."]),
